/// A broadcast grid (Cartesian product) of two 1-D `f32` arrays.
/// 
/// The shape is always `(x.len(), y.len())`.  For any valid indices
/// `0 <= i < x.len()` and `0 <= j < y.len()`, 
/// calling `.at(i, j)` returns `(x[i], y[j])`.
#[derive(Debug, Clone)]
pub struct BroadcastObject {
    /// Number of rows  = length of the first input array
    shape: (usize, usize),
    /// The first input array
    x: Vec<f32>,
    /// The second input array
    y: Vec<f32>,
}

impl BroadcastObject {
    /// Returns the shape of the broadcast grid: (rows, columns)
    pub fn shape(&self) -> (usize, usize) {
        self.shape
    }

    /// Returns the element at position `(i, j)`.
    /// 
    /// Panics if `i >= self.shape().0` or `j >= self.shape().1`.
    pub fn at(&self, i: usize, j: usize) -> (f32, f32) {
        // Indexing inside bounds is guaranteed by the call sites
        (self.x[i], self.y[j])
    }
}

/// Constructs a `BroadcastObject` representing the Cartesian product
/// of `x` and `y`.  Both vectors must be non‐empty.
pub fn broadcast(x: Vec<f32>, y: Vec<f32>) -> BroadcastObject {
    // We assume x.len() > 0 and y.len() > 0 as per problem statement.
    let shape = (x.len(), y.len());
    BroadcastObject { shape, x, y }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_broadcast_simple() {
        let x = vec![1.0, 2.0, 3.0];
        let y = vec![0.5, 1.5];
        let b = broadcast(x.clone(), y.clone());

        // shape should be (3, 2)
        assert_eq!(b.shape(), (3, 2));

        // check all pairs
        for i in 0..3 {
            for j in 0..2 {
                let (xi, yj) = b.at(i, j);
                assert_eq!(xi, x[i]);
                assert_eq!(yj, y[j]);
            }
        }
    }

    #[test]
    fn test_broadcast_single_length() {
        let x = vec![42.0];
        let y = vec![7.0, 8.0, 9.0];
        let b = broadcast(x.clone(), y.clone());
        assert_eq!(b.shape(), (1, 3));
        for j in 0..3 {
            assert_eq!(b.at(0, j), (42.0, y[j]));
        }
    }
}